const out = {};
function dump(n, depth) {
  if (depth > 4) return null;
  const o = {id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height)};
  if (n.type === 'TEXT') { o.chars = n.characters; o.font = n.fontName; o.size = n.fontSize; try{o.fills = JSON.parse(JSON.stringify(n.fills));}catch(e){} }
  if ('fills' in n && n.type !== 'TEXT') { try { o.fills = JSON.parse(JSON.stringify(n.fills)); } catch(e){} }
  if ('cornerRadius' in n) o.r = n.cornerRadius;
  if ('strokes' in n && n.strokes && n.strokes.length) { o.strokes = JSON.parse(JSON.stringify(n.strokes)); o.sw = n.strokeWeight; }
  if ('children' in n) o.children = n.children.map(c => dump(c, depth+1)).filter(Boolean);
  return o;
}
