const ids = ['4:115','4:118','4:121','4:124','4:127','4:130','4:133','4:136','4:139','4:142','4:145','4:148','4:151','4:154','4:157','4:160','4:163','4:13','4:16','4:10','4:103','4:106','4:109','4:91','4:94','4:97','4:22'];
const out = {};
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  const fills = new Set();
  const walk = (x) => {
    if ('fills' in x && x.fills && x.fills.length) {
      for (const f of x.fills) {
        if (f.type === 'SOLID') fills.add(`SOLID ${Math.round(f.color.r*255)},${Math.round(f.color.g*255)},${Math.round(f.color.b*255)} op${f.opacity}`);
        else if (f.type === 'IMAGE') fills.add('IMAGE ' + (f.imageHash||'').slice(0,8));
        else fills.add(f.type);
      }
    }
    if ('children' in x) x.children.forEach(walk);
  };
  walk(n);
  out[n.name] = [...fills];
}
return JSON.stringify(out);

function dump(n, d) {
  if (d>3) return null;
  const o = {id:n.id, name:n.name, type:n.type};
  if ('fills' in n && n.fills && n.fills.length) o.fills = n.fills.map(f=> f.type==='SOLID'? `S ${Math.round(f.color.r*255)},${Math.round(f.color.g*255)},${Math.round(f.color.b*255)} op${f.opacity}` : f.type);
  if ('children' in n) o.ch = n.children.map(c=>dump(c,d+1)).filter(Boolean);
  return o;
}
