// helper: section with header + horizontal row of product cards
function section(title, cards){
  const shi=SH.createInstance();f.appendChild(shi);shi.layoutSizingHorizontal='FILL';
  const titleNode=shi.findOne(n=>n.type==='TEXT'&&n.characters==='Section Title');
  if(titleNode)titleNode.characters=title;
  const row=figma.createFrame();row.name=title+' Row';row.layoutMode='HORIZONTAL';row.itemSpacing=12;row.paddingLeft=24;row.paddingRight=24;row.paddingBottom=20;row.fills=[];
  f.appendChild(row);row.layoutSizingHorizontal='FILL';
  for(const c of cards){
    const inst=PC.createInstance();row.appendChild(inst);
    const img=inst.findOne(n=>n.name==='Image');
    if(img)img.fills=imgFill(c.img);
    const nameT=inst.findOne(n=>n.type==='TEXT'&&n.characters==='Product Name');
    if(nameT)nameT.characters=c.name;
    const unitT=inst.findOne(n=>n.type==='TEXT'&&n.characters==='1kg');
    if(unitT)unitT.characters=c.unit;
    const priceT=inst.findOne(n=>n.type==='TEXT'&&n.characters==='$4.99');
    if(priceT)priceT.characters=c.price;
  }
  return row;
}

