function accordion(title, open, content){
  const acc=figma.createFrame();acc.name='Accordion '+title;acc.layoutMode='VERTICAL';acc.itemSpacing=0;acc.paddingLeft=24;acc.paddingRight=24;acc.fills=[];
  f6.appendChild(acc);acc.layoutSizingHorizontal='FILL';
  const head=figma.createFrame();head.name='Head';head.layoutMode='HORIZONTAL';head.counterAxisAlignItems='CENTER';head.paddingTop=14;head.paddingBottom=14;head.fills=[];head.primaryAxisSizingMode='AUTO';head.counterAxisSizingMode='AUTO';
  acc.appendChild(head);head.layoutSizingHorizontal='FILL';
  const ht=T(title,15,'Semi Bold',C.ink);head.appendChild(ht);ht.layoutGrow=1;
  const chev=figma.createVector();chev.name='Chevron';chev.vectorPaths=[{data:open?'M 0 0 L 6 6 L 12 0':'M 0 0 L 6 6 L 12 0',windingRule:'NONZERO'}];chev.strokes=solid(C.muted);chev.strokeWeight=2;chev.strokeCap='ROUND';chev.strokeJoin='ROUND';chev.fills=[];chev.resize(12,6);
  if(!open)chev.rotation=180;
  head.appendChild(chev);
  const line=figma.createFrame();line.name='Line';line.resize(366,1);line.fills=solid(C.line);
  acc.appendChild(line);line.layoutSizingHorizontal='FILL';
  if(open&&content){
    const body=figma.createFrame();body.name='Body';body.layoutMode='VERTICAL';body.paddingTop=12;body.paddingBottom=14;body.fills=[];body.primaryAxisSizingMode='AUTO';body.counterAxisSizingMode='AUTO';
    acc.appendChild(body);body.layoutSizingHorizontal='FILL';
    const ct=T(content,13,'Regular',C.muted);ct.resize(366,ct.height);ct.textAutoResize='HEIGHT';
    body.appendChild(ct);
  }
  return acc;
}
